    body += at(3, 'pop', `<rect x="${gx - 44}" y="${GY - 30}" width="12" height="40" fill="${C.ink}"/><rect x="${gx + 32}" y="${GY - 30}" width="12" height="40" fill="${C.ink}"/><path d="M${gx - 32} ${GY - 22} H${gx + 32}" stroke="${C.red}" stroke-width="7"/><path d="M${gx - 32} ${GY - 22} H${gx + 32}" stroke="white" stroke-width="7" stroke-dasharray="10 10"/>`, 0.1);
    body += at(3, 'pop', person(gx, GY + 48, C.green, 1.1) + `<rect x="${gx + 12}" y="${GY + 14}" width="22" height="16" rx="2" fill="white" stroke="${C.blue}" stroke-width="2.5"/>`, 0.6);
