    const ROUTE = [[131.89, 43.12], [135.07, 48.48], [123.9, 53.98], [113.5, 52.03], [107.6, 51.83], [104.3, 52.29], [92.87, 56.01], [82.92, 55.03], [73.37, 54.98], [60.6, 56.84], [44.0, 56.33], [37.62, 55.75]];
    const q = ROUTE.map((p) => P(v, ...p)), d = 'M' + q.map((p) => p.join(' ')).join(' L');
    const VL = q[0], MO = q[q.length - 1];
    body += lab(...P(v, 95, 63), '러시아', { size: 22, color: C.muted });
    // 1칸: 두 도시
    body += at(1, 'pop', dot(...VL, 7, C.red) + tag(VL[0] + 6, VL[1] + 30, '블라디보스토크', RED, { size: 18 }), 0.2);
    body += at(1, 'pop', dot(...MO, 7, C.red) + tag(MO[0] + 10, MO[1] - 30, '모스크바', RED, { size: 18 }), 0.6);
    // 2칸: 동쪽에서 서쪽으로 철길
    body += drawn(2, d, C.purple, 5, '', 1.8, 0.1);
    body += shown(2, `<path class="run" d="${d}" fill="none" stroke="white" stroke-width="2" stroke-dasharray="6 18"/>`);
    // 3칸: 이름과 길이
    body += blink(3, `<path d="${d}" fill="none" stroke="${C.yellow}" stroke-width="11" stroke-opacity=".7" stroke-linejoin="round"/>`, 0.1);
    body += at(3, 'pop', tag(...P(v, 80, 46.5), '시베리아 횡단 철도', HOT, { size: 22 }), 0.4);
    body += at(3, 'pop', tag(...P(v, 80, 41.5), '9,000 km 넘게', PLAIN, { size: 18 }), 0.8);
    put(KEY('11', '시베리아 횡단 철도'), svg(id, body, css));
